Object.assign(window.TEM8_DICTIONARY, {"biotechnology":{"oxford":{"phon":"ˌbaɪəʊtekˈnɒlədʒi","pos":"noun","senses":[{"en":"the use of living cells and bacteria in industrial and scientific processes","cn":"生物技术"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"生物技术","en":"Biotechnology is the use of living parts such as cells or bacteria in industry and technology."}]},"media":{"uk":"media/uk/biotechnology__gb_1.mp3","us":"media/us/biotechnology__us_1.mp3"},"examples":[{"en":"biotechnological research","cn":"生物科技研究"},{"en":"the biotech industries","cn":"生物技术产业"}]},"biting":{"oxford":{"phon":"ˈbaɪtɪŋ","pos":"adjective","senses":[{"en":"very cold and unpleasant","cn":"刺骨的；凛冽的","ex":{"en":"He shivered in the biting cold.","cn":"他在刺骨的寒冷中瑟瑟发抖。"}},{"en":"cruel and critical","cn":"刻薄的；辛辣的","ex":{"en":"biting sarcasm/wit","cn":"尖酸刻薄的讽刺／俏皮话"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"寒冷的；刺骨的；凛冽的","en":"Biting wind or cold is extremely cold.","ex":{"en":"...a raw, biting northerly wind","cn":"阴冷刺骨的北风"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"刻薄的；尖刻的；辛辣的","en":"Biting criticism or wit is very harsh or unkind, and is often caused by such feelings as anger or dislike.","ex":{"en":"...a furore caused by the author's biting satire on the Church","cn":"作者对教会尖刻的讽刺引发的公愤"}}]},"media":{"uk":"media/uk/biting__gb_1.mp3","us":"media/us/biting__us_1.mp3"},"examples":[{"en":"biting sarcasm/wit","cn":"尖酸刻薄的讽刺/俏皮话"},{"en":"A biting wind blew down from the hills.","cn":"山上吹来刺骨的寒风。"}]},"big":{"media":{"uk":"media/uk/big__gb_1.mp3","us":"media/us/big__us_1.mp3"},"oxford":{"phon":"bɪɡ","pos":"adjective","senses":[{"en":"large in size, degree, amount, etc.","cn":"（体积、程度、数量等）大的，巨大的","lab":"informal","sc":"large","ex":{"en":"a big man/house/increase","cn":"高大的男人；大房子；大幅度增长"}},{"en":"older","cn":"年龄较大","lab":"informal","sc":"older","ex":{"en":"my big brother","cn":"我哥哥"}},{"en":"important; serious","cn":"重大的；严重的","g":"[only before noun]","lab":"rather informal","sc":"important","ex":{"en":"It's a big decision to have to make.","cn":"这是不得不做的一个重大决定。"}},{"en":"needing a lot of effort, money or time to succeed","cn":"庞大的；宏大的","lab":"informal","sc":"ambitious","ex":{"en":"They're full of big ideas.","cn":"他们满怀勃勃雄心。"}},{"en":"popular with the public; successful","cn":"大受欢迎的；成功的","lab":"informal","sc":"popular","ex":{"en":"Orange is the big colour this year.","cn":"橘黄色是今年的流行色。"}},{"en":"enthusiastic about somebody/something","cn":"热衷于…的；狂热的","lab":"informal","sc":"enthusiastic","ex":{"en":"I'm a big fan of hers.","cn":"我是她的狂热追随者。"}},{"en":"doing something often or to a large degree","cn":"经常（或大量）做某事的","sc":"doing something a lot","ex":{"en":"a big eater/drinker/spender","cn":"食量大的／有酒量的／花钱手大的人"}},{"en":"kind or generous","cn":"大方的；慷慨的","lab":"usually ironic","sc":"generous","ex":{"en":"He gave me an extra five pounds for two hours' work. I thought ‘That's big of you’.","cn":"我做两小时的工作他多给我五英镑。我心想“您真大方”。"}},{"en":"in an impressive way","cn":"大大；给人印象深地","ex":{"en":"We need to think big.","cn":"我们应该考虑干一番大事。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人或物）大的","en":"A big person or thing is large in physical size.","ex":{"en":"Australia's a big country","cn":"澳大利亚是个幅员辽阔的国家。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"数量多的","en":"Something that is big consists of many people or things.","ex":{"en":"The crowd included a big contingent from Ipswich.","cn":"人群中有来自伊普斯威奇的一个人数众多的代表团。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严重的；重大的；大幅度的","en":"If you describe something such as a problem, increase, or change as a big one, you mean it is great in degree, extent, or importance.","ex":{"en":"Her problem was just too big for her to tackle on her own","cn":"她的问题太严重了，光靠她自己是没法解决的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"规模大的","en":"A big organization employs many people and has many customers.","ex":{"en":"Exchange is largely controlled by big banks.","cn":"货币兑换业务主要由大银行控制。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"影响大的；职位高的","en":"If you say that someone is big in a particular organization, activity, or place, you mean that they have a lot of influence or authority in it.","ex":{"en":"Their father was very big in the army","cn":"他们的父亲在军中很有影响力。"}},{"pos":"ADJ 形容词","cn":"（强调厌恶之深）十足的，突出的","en":"If you call someone a big bully or a big coward, you are emphasizing your disapproval of them."},{"pos":"ADJ 形容词","cn":"年龄较大的；年长的","en":"Children often refer to their older brother or sister as their big brother or sister."},{"pos":"ADJ 形容词","cn":"（字母）大写的","en":"Capital letters are sometimes referred to as big letters.","ex":{"en":"...a big letter J.","cn":"大写字母J"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（字词）大的，生僻的，不常用的","en":"Big words are long or rare words which have meanings that are difficult to understand.","ex":{"en":"They use a lot of big words.","cn":"他们使用很多生僻的词汇。"}},{"pos":"PHRASE 短语","cn":"取得成功；出名","en":"If you make it big, you become successful or famous.","ex":{"en":"We're not just looking at making it big in the UK, we want to be big internationally.","cn":"我们不仅想在英国取得成功，还想在国际上扬名立万。"}},{"pos":"PHRASE 短语","cn":"雄心勃勃；志向远大","en":"If you think big, you make plans on a large scale, often using a lot of time, effort, or money.","ex":{"en":"Maybe we're not thinking big enough.","cn":"也许我们的抱负还不够远大。"}},{"pos":"PHRASE 短语","cn":"大规模地；广泛地","en":"If something is happening in a big way, it is happening on a large scale.","ex":{"en":"I think boxing will take off in a big way here.","cn":"我想拳击运动在这儿会有很大的发展。"}}]},"examples":[{"en":"He gave me an extra five pounds for two hours' work. I thought ‘That's big of you’.","cn":"我做两小时的工作他多给我五英镑。我心想“您真大方”。"},{"en":"Ladies and gentlemen, let's give a big hand to our special guests tonight.","cn":"女士们、先生们，让我们热烈鼓掌欢迎今晚的特邀嘉宾。"}]},"bite":{"oxford":{"phon":"baɪt","pos":"verb","senses":[{"en":"to use your teeth to cut into or through something","cn":"咬","g":"[intransitive, transitive]","sc":"use teeth","ex":{"en":"Does your dog bite?","cn":"你的狗咬人吗？"}},{"en":"to wound somebody by making a small hole or mark in their skin","cn":"叮；蜇；咬","g":"[intransitive, transitive]","sc":"of insect/snake","ex":{"en":"Most European spiders don't bite.","cn":"大多数欧洲蜘蛛不咬人。"}},{"en":"if a fish bites, it takes food from the end of a fishing line and may get caught","cn":"咬饵；上钩","g":"[intransitive]","sc":"of fish"},{"en":"to have an unpleasant effect","cn":"产生不良影响","g":"[intransitive]","sc":"have effect","ex":{"en":"The recession is beginning to bite.","cn":"经济衰退开始产生不良影响。"}},{"en":"an act of biting","cn":"咬","g":"[countable]","sc":"using teeth","ex":{"en":"The dog gave me a playful bite.","cn":"狗闹着玩地咬了我一下。"},"pos":"noun"},{"en":"the way the upper and lower teeth fit together","cn":"（上、下牙的）咬合；啮合","g":"[countable, usually singular]","sc":"using teeth","ex":{"en":"He has to wear a brace to correct his bite.","cn":"他得戴上牙箍来矫正牙齿的咬合。"},"pos":"noun"},{"en":"a small piece of food that you can bite from a larger piece","cn":"（咬下的）一口","g":"[countable]","sc":"food","ex":{"en":"She took a couple of bites of the sandwich.","cn":"她吃了两口三明治。"},"pos":"noun"},{"en":"a small amount of food; a small meal","cn":"少量食物；简单的一餐","g":"[singular]","lab":"informal","sc":"food","ex":{"en":"How about a bite of lunch?","cn":"简单吃点午饭好吗？"},"pos":"noun"},{"en":"a wound made by an animal or insect","cn":"咬伤；叮伤；蜇伤","g":"[countable]","sc":"of insect/animal","ex":{"en":"Dog bites can get infected.","cn":"狗咬的伤口会感染。"},"pos":"noun"},{"en":"a pleasant strong taste","cn":"浓香","g":"[uncountable]","sc":"strong taste","ex":{"en":"Cheese will add extra bite to any pasta dish.","cn":"干酪会增加面食的香味。"},"pos":"noun"},{"en":"a sharp cold feeling","cn":"寒冷；凛冽","g":"[singular]","sc":"cold","ex":{"en":"There's a bite in the air tonight.","cn":"今晚寒气刺骨。"},"pos":"noun"},{"en":"a quality that makes something effective or powerful","cn":"影响力；感染力","g":"[uncountable]","sc":"powerful effect","ex":{"en":"The performance had no bite to it.","cn":"这次演出毫无感染力。"},"pos":"noun"},{"en":"the act of a fish biting food on a hook","cn":"咬饵；上钩","g":"[countable]","sc":"of fish","ex":{"en":"The fishermen waited all afternoon for a bite.","cn":"渔民们整整等待了一个下午。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"咬；咬伤","en":"If you bite something, you use your teeth to cut into it, for example in order to eat it or break it. If an animal or person bites you, they use their teeth to hurt or injure you.","ex":{"en":"Both sisters bit their nails as children","cn":"两姐妹都像小孩儿一样咬指甲。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指对食物的）咬","en":"A bite of something, especially food, is the action of biting it.","ex":{"en":"He took another bite of apple","cn":"他又咬了一口苹果。"}},{"pos":"N-SING 单数名词","cn":"一点儿食物","en":"If you have a bite to eat, you have a small meal or a snack.","ex":{"en":"It was time to go home for a little rest and a bite to eat.","cn":"该回家休息一会儿，吃一点儿东西了。"}},{"pos":"VERB 动词","cn":"咬；叮","en":"If a snake or a small insect bites you, it makes a mark or hole in your skin, and often causes the surrounding area of your skin to become painful or itchy.","ex":{"en":"When an infected mosquito bites a human, spores are injected into the blood","cn":"感染病毒的蚊子叮咬人之后，孢子便被注入血液中。"}},{"pos":"N-COUNT 可数名词","cn":"（被叮、咬后留下的）伤口，包","en":"A bite is an injury or a mark on your body where an animal, snake, or small insect has bitten you.","ex":{"en":"Any dog bite, no matter how small, needs immediate medical attention.","cn":"被狗咬后，不管伤口多小，都必须立即就医。"}},{"pos":"VERB 动词","cn":"产生严重（或不良）影响","en":"When an action or policy begins to bite, it begins to have a serious or harmful effect.","ex":{"en":"As the sanctions begin to bite there will be more political difficulties ahead","cn":"随着制裁开始产生严重的负面影响，政治上将面临更多的困难。"}},{"pos":"VERB 动词","cn":"碾轧；切割；陷入","en":"If an object bites into a surface, it presses hard against it or cuts into it.","ex":{"en":"There may even be some wire or nylon biting into the flesh","cn":"甚至可能有一些金属丝或者尼龙线勒到肉里。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（食物或酒的）浓郁味道，辛辣味","en":"If you say that a food or drink has bite, you like it because it has a strong or sharp taste.","ex":{"en":"...the addition of tartaric acid to give the wine some bite.","cn":"为增加红酒的口感而加入酒石酸"}},{"pos":"N-SING 单数名词","cn":"寒冷；刺骨","en":"If the air or the wind has a bite, it feels very cold.","ex":{"en":"There was a bite in the air, a smell perhaps of snow.","cn":"空气非常寒冷，似乎有雪的味道。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（表演、文章等的）犀利，感染力","en":"If something such as a performance or a piece of writing has bite, it is exciting or effective.","ex":{"en":"The teams have that extra bite when they are playing against their neighbours","cn":"这几支队伍与其邻近地区队伍交手时锐气更盛。"}},{"pos":"VERB 动词","cn":"上钩；咬钩；吞饵","en":"If a fish bites when you are fishing, it takes the hook or bait at the end of your fishing line in its mouth.","ex":{"en":"After half an hour, the fish stopped biting and we moved on.","cn":"半个小时以后，鱼儿不再咬钩了，我们只好换地方。"}},{"pos":"N-COUNT 可数名词","cn":"少许；少量；小部分","en":"A bite of something is a small part or amount of it.","ex":{"en":"...bites of conversation.","cn":"谈话的片段"}},{"pos":"PHRASE 短语","cn":"恩将仇报；以怨报德；忘恩负义","en":"If someone bites the hand that feeds them, they behave badly or in an ungrateful way towards someone who they depend on.","ex":{"en":"She may be cynical about the film industry, but ultimately she has no intention of biting the hand that feeds her.","cn":"她对电影业可能有些怀疑失望，但终究没有恩将仇报之意。"}},{"pos":"PHRASE 短语","cn":"大发雷霆；乱发火儿","en":"If someone speaks or replies to you angrily, and you think they are being unfair or reacting too strongly, you can say that they bite your head off .","ex":{"en":"Whenever possible, suggest she talks about it but be aware she may bite your head off for your trouble.","cn":"找机会建议她谈谈这事儿，但是小心她可能会因为你多事儿而大发雷霆。"}},{"pos":"PHRASE 短语","cn":"隐忍不言；绷紧嘴巴","en":"If you bite your lip or your tongue, you stop yourself from saying something that you want to say, because it would be the wrong thing to say in the circumstances.","ex":{"en":"I must learn to bite my lip","cn":"我必须学会不乱说话。"}},{"pos":"PHRASE 短语","cn":"抽出一部分，拿出一部分（钱）","en":"If something takes a bite out of a sum of money, part of the money is spent or taken away in order to pay for it.","ex":{"en":"Local taxes are going to be taking a bigger bite out of people's income than they ever have before.","cn":"地方税收在人们收入中的比重将超过以往任何时候。"}},{"pos":"","cn":"","en":"someone's bark is worse than their bite→see: ; to bite the bullet→see: ; to bite off more than one can chew→see: ; to bite the dust→see: ; to bite the dust→see: ; once bitten→see: ;"},{"pos":"","cn":"","en":"相关词组：bite back"}]},"media":{"uk":"media/uk/bite__gb_1.mp3","us":"media/us/bite__us_1.mp3","img":["media/ldoce/img/bite.jpg"]},"examples":[{"en":"We just have time for a bite to eat before the movie.","cn":"电影开演之前，我们只够时间匆匆吃一点东西。"},{"en":"I didn't believe her explanation but I bit my tongue.","cn":"我不相信她的解释，但我忍着没有说出来。"}]},"birth":{"media":{"uk":"media/uk/birth__gb_1.mp3","us":"media/us/birth__us_1.mp3"},"oxford":{"phon":"bɜːθ","pos":"noun","senses":[{"en":"the time when a baby is born; the process of being born","cn":"出生；诞生；分娩","g":"[uncountable, countable]","lab":"especially US English","ex":{"en":"The baby weighed three kilos at birth.","cn":"婴儿出生时体重为三公斤。"}},{"en":"the beginning of a new situation, idea, place, etc.","cn":"创始；起源","g":"[singular]","ex":{"en":"This declaration marked the birth of a new society in South Africa.","cn":"这份宣言标志着一个新社会在南非诞生了。"}},{"en":"a person’s origin or the social position of their family","cn":"出身；门第","g":"[uncountable]","ex":{"en":"Anne was French by birth but lived most of her life in Italy.","cn":"安妮在血统上是法国人，但一生大部分时间住在意大利。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"出生；降生；出世","en":"When a baby is born, you refer to this event as his or her birth .","ex":{"en":"It was the birth of his grandchildren which gave him greatest pleasure","cn":"孙子孙女的出生给他带来了极大的快乐。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"诞生；产生；出现；起源","en":"You can refer to the beginning or origin of something as its birth .","ex":{"en":"...the birth of popular democracy.","cn":"人民民主的诞生"}},{"pos":"N-UNCOUNT 不可数名词","cn":"出身；家世；门第","en":"Some people talk about a person's birth when they are referring to the social position of the person's family.","ex":{"en":"...men of low birth","cn":"出身卑微的人"}},{"pos":"PHRASE 短语","cn":"在血统上；生来","en":"If, for example, you are French by birth, you are French because your parents are French, or because you were born in France.","ex":{"en":"Sadrudin was an Iranian by birth.","cn":"萨德尔丁是伊朗血统。"}},{"pos":"PHRASE 短语","cn":"生（孩子）；分娩；生育","en":"When a woman gives birth, she produces a baby from her body.","ex":{"en":"She's just given birth to a baby girl","cn":"她刚生了一个女孩。"}},{"pos":"PHRASE 短语","cn":"使产生；使诞生","en":"To give birth to something such as an idea means to cause it to start to exist.","ex":{"en":"In 1980, strikes at the Lenin Shipyards gave birth to the Solidarity trade union.","cn":"1980年，列宁造船厂的罢工致使团结工会得以成立。"}},{"pos":"PHRASE 短语","cn":"出生的（地方）","en":"The country, town, or village of your birth is the place where you were born."}]},"examples":[{"en":"Anne was French by birth but lived most of her life in Italy.","cn":"安妮在血统上是法国人，但大部分时间住在意大利。"},{"en":"John was present at the birth of both his children.","cn":"约翰的两个孩子出生时他均在场。"}]},"birdsong":{"media":{"uk":"media/uk/birdsong__gb_1.mp3","us":"media/us/birdsong__us_1.mp3"},"oxford":{"phon":"ˈbɜːdsɒŋ","pos":"noun","senses":[{"en":"the musical sounds made by birds","cn":"（婉转动听的）鸟鸣","ex":{"en":"The woods were full of sunlight and birdsong.","cn":"树林里充满了阳光和鸟鸣。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"鸟鸣","en":"Birdsong is the sound of a bird or birds calling in a way which sounds musical.","ex":{"en":"The air is filled with birdsong.","cn":"处处闻啼鸟。"}}]}},"biotech":{"oxford":{"phon":"ˌbaɪəʊtekˈnɒlədʒi","pos":"noun","senses":[{"en":"the use of living cells and bacteria in industrial and scientific processes","cn":"生物技术"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 biotechnology","en":"Biotech means the same as biotechnology .","ex":{"en":"...the biotech industry.","cn":"生物技术行业"}}]}},"bilingual":{"media":{"uk":"media/uk/bilingual__gb_1.mp3","us":"media/us/bilingual__us_1.mp3"},"oxford":{"phon":"ˌbaɪˈlɪŋɡwəl","pos":"noun","senses":[{"en":"a person who can speak two languages equally well","cn":"会说两种语言的","ex":{"en":"Welsh/English bilinguals","cn":"会说威尔士语和英语两种语言的人"}},{"en":"able to speak two languages equally well","cn":"会说两种语言的","ex":{"en":"She is bilingual in English and Punjabi.","cn":"她会说英语和旁遮普语。"},"pos":"adjective"},{"en":"using two languages; written in two languages","cn":"用两种语言（写）的","ex":{"en":"bilingual education/communities","cn":"双语教育／社群"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"双语的；涉及两种语言的；使用两种语言的","en":"Bilingual means involving or using two languages.","ex":{"en":"...bilingual education.","cn":"双语教育"}},{"pos":"ADJ 形容词","cn":"双语的；能说两种语言的","en":"Someone who is bilingual can speak two languages equally well, usually because they learned both languages as a child.","ex":{"en":"He is bilingual in an Asian language and English.","cn":"他会说一门亚洲语言和一门英语。"}}]},"examples":[{"en":"She is bilingual in English and Punjabi.","cn":"她会说英语和旁遮普语。"},{"en":"Welsh/English bilinguals","cn":"会说威尔士语和英语的人"}]},"biographical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"传记的；关于生平的","en":"Biographical facts, notes, or details are concerned with the events in someone's life.","ex":{"en":"The book contains few biographical details.","cn":"这本书没有什么生平细节。"}}]},"media":{"uk":"media/uk/biographical__gb_1.mp3","us":"media/us/biographical__us_1.mp3"},"examples":[{"en":"Boswell’s biography of Samuel Johnson","cn":""}],"oxford":{"phon":"ˌbaɪəˈɡræfɪkl","pos":"adjective","senses":[{"en":"telling the story of a person's life","cn":"讲述一个人的生活故事"},{"en":"connected with a person's life","cn":"生平的","ex":{"en":"biographical information/details","cn":"传记信息/详细信息"}}]}},"birthday":{"media":{"uk":"media/uk/birthday__gb_1.mp3","us":"media/us/birthday__us_1.mp3"},"oxford":{"phon":"ˈbɜːθdeɪ","pos":"noun","senses":[{"en":"the day in each year which is the same date as the one on which you were born","cn":"生日","ex":{"en":"Happy Birthday!","cn":"生日快乐！"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"生日","en":"Your birthday is the anniversary of the date on which you were born."}]},"examples":[{"en":"Happy Birthday!","cn":"生日快乐！"},{"en":"Oliver's 13th birthday","cn":"奥利弗的 13 岁生日"}]},"bid":{"media":{"uk":"media/uk/bid__gb_1.mp3","us":"media/us/bid__us_1.mp3"},"oxford":{"phon":"bɪd","pos":"noun","senses":[{"en":"an offer by a person or a company to pay a particular amount of money for something","cn":"（买方的）出价","lab":"North American English also","ex":{"en":"A German firm launched a takeover bid for the company.","cn":"一家德国公司出价收购这家公司。"}},{"en":"an offer to do work or provide a service for a particular price, in competition with other companies, etc.","cn":"投标","lab":"North American English also","ex":{"en":"The company submitted a bid for the contract to clean the hospital.","cn":"该公司投标承包这所医院的清洁工作。"}},{"en":"an effort to do something or to obtain something","cn":"努力争取","ex":{"en":"a bid for power","cn":"权力之争"}},{"en":"a statement of the number of points a player thinks they will win","cn":"叫牌；叫出的点数"},{"en":"to offer to pay a particular price for something, especially at an auction","cn":"出（价）；（尤指拍卖中）喊价","g":"[intransitive, transitive]","ex":{"en":"I bid £2 000 for the painting.","cn":"我出 2 000 英镑买这幅画。"},"pos":"verb"},{"en":"to offer to do work or provide a service for a particular price, in competition with other companies, etc.","cn":"投标","g":"[intransitive]","lab":"North American English also","ex":{"en":"A French firm will be bidding for the contract.","cn":"一家法国公司将投标争取这项合同。"},"pos":"verb"},{"en":"to try to do, get or achieve something","cn":"努力争取；企图获得","g":"[transitive]","ex":{"en":"The team is bidding to retain its place in the league.","cn":"这个队正争取保住它在联赛中的位置。"},"pos":"verb"},{"en":"(in some card games) to say how many points you expect to win","cn":"（某些牌戏中）叫牌；叫出的点数","g":"[transitive, intransitive]","ex":{"en":"She bid four hearts.","cn":"她叫四红桃。"},"pos":"verb"},{"en":"to say ‘good morning’, etc. to somebody","cn":"向（某人）问候、道别等","lab":"formal","ex":{"en":"I bade farewell to all the friends I had made in Paris.","cn":"我告别了我在巴黎结交的所有朋友。"},"pos":"verb"},{"en":"to tell somebody to do something","cn":"告诉（某人做某事）；吩咐","lab":"old use or literary","ex":{"en":"He bade me come closer.","cn":"他让我靠近些。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"努力；尝试；企图","en":"A bid for something or a bid to do something is an attempt to obtain it or do it.","ex":{"en":"...Sydney's successful bid for the 2000 Olympic Games","cn":"悉尼对2000年奥运会的成功申办"}},{"pos":"N-COUNT 可数名词","cn":"投标；出价","en":"A bid is an offer to pay a particular amount of money for something that is being sold.","ex":{"en":"Hanson made an agreed takeover bid of £351 million.","cn":"汉森按协商出价3.51亿英镑接管该公司。"}},{"pos":"VERB 动词","cn":"努力争取；尝试","en":"If you bid for something or bid to do something, you try to obtain it or do it.","ex":{"en":"Singapore Airlines is rumoured to be bidding for a management contract to run both airports","cn":"据传，新加坡航空公司正在争取签下两家机场的经营权。"}},{"pos":"VERB 动词","cn":"投标；竞标；出价","en":"If you bid for something that is being sold, you offer to pay a particular amount of money for it.","ex":{"en":"She decided to bid for a Georgian dressing table","cn":"她决定参与一个乔治王朝时期风格梳妆台的竞价。"}},{"pos":"","cn":"","en":"相关词组：bid up"},{"pos":"VERB 动词","cn":"道（别、晚安等）","en":"If you bid someone farewell, you say goodbye to them. If you bid them goodnight, you say goodnight to them.","ex":{"en":"She bade farewell to her son","cn":"她和儿子道了别。"}},{"pos":"VERB 动词","cn":"要求；邀请","en":"If you bid someone do something, you ask or invite them to do it.","ex":{"en":"They all smiled at him and bade him eat","cn":"他们都朝他微笑，请他吃饭。"}}]},"examples":[{"en":"We wanted to buy the chairs but another couple were bidding against us.","cn":"我们想买下那几把椅子，但另一对夫妇在同我们较劲出价。"},{"en":"At the auction (= a public sale where things are sold to the person who offers the most), the highest bid for the picture was £200.","cn":"拍卖会上，这幅画的最高出价为 200 英镑。"}]},"big-ticket":{"oxford":{"phon":"ˈbɪɡ tɪkɪt","pos":"adjective","senses":[{"en":"costing a lot of money","cn":"高价的","ex":{"en":"big-ticket items","cn":"高价项目"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"高价的；昂贵的","en":"If you describe something as a big-ticket item, you mean that it costs a lot of money.","ex":{"en":"Supercomputers are big-ticket items.","cn":"超级计算机价格昂贵。"}}]},"media":{"uk":"media/uk/big_ticket_1_gb_1.mp3","us":"media/us/big_ticket_1_us_1.mp3"},"examples":[{"en":"big-ticket items","cn":"高价项目"}]},"bin":{"media":{"uk":"media/uk/bin__gb_1.mp3","us":"media/us/bin__us_1.mp3","img":["media/ldoce/img/ldoce_025.png"]},"oxford":{"phon":"bɪn","pos":"noun","senses":[{"en":"a container that you put waste in","cn":"垃圾箱","lab":"especially British English","ex":{"en":"a rubbish bin","cn":"垃圾箱"}},{"en":"a large container, usually with a lid (= cover), for storing things in","cn":"（有盖）大容器，箱，柜","ex":{"en":"a bread bin","cn":"面包箱"}},{"en":"to throw something away","cn":"扔掉；丢弃","ex":{"en":"Do you need to keep these letters or shall we bin them?","cn":"你需要保存这些信件吗，还是干脆把它们扔掉？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"垃圾桶；垃圾箱","en":"A bin is a container that you put rubbish in.","ex":{"en":"He screwed the paper small and chucked it in the bin.","cn":"他把纸揉成小团，扔进了垃圾桶。"}},{"pos":"N-COUNT 可数名词","cn":"箱子；储物箱；储藏箱","en":"A bin is a container that you keep or store things in.","ex":{"en":"...a bread bin.","cn":"面包箱"}},{"pos":"VERB 动词","cn":"扔掉","en":"If you bin something, you throw it away.","ex":{"en":"He decided to bin his paintings.","cn":"他决定把他的画扔掉。"}}]},"examples":[{"en":"Do you need to keep these letters or shall we bin them?","cn":"你需要保存这些信件吗，还是干脆把它们扔掉？"},{"en":"a rubbish bin","cn":"垃圾箱"}]},"binds":{"oxford":{"phon":"baɪnd","pos":"verb","senses":[{"en":"( formal ) to tie sb/sth with rope, string, etc. so that they cannot move or are held together firmly","cn":"捆绑；系"},{"en":"( formal ) to tie a long thin piece of cloth around sth （","cn":"用长布条）缠绕"}]}},"bird":{"media":{"img":["media/pic/birds_comp.jpg","media/thumb/finch.jpg"],"uk":"media/uk/bird__gb_1.mp3","us":"media/us/bird__us_1.mp3"},"oxford":{"phon":"bɜːd","pos":"noun","senses":[{"en":"a creature that is covered with feathers and has two wings and two legs. Most birds can fly.","cn":"鸟；禽","ex":{"en":"a bird’s nest with two eggs in it","cn":"内有两只鸟蛋的鸟窝"}},{"en":"a person of a particular type, especially somebody who is strange or unusual in some way","cn":"某类人；（尤指）古怪的人，不寻常的人","lab":"informal","ex":{"en":"a wise old bird","cn":"处世老练的人"}},{"en":"an offensive way of referring to a young woman","cn":"小妞儿，小姐（有些人认为该词具有冒犯性）","lab":"British English, old-fashioned, slang, offensive，，，，，，"},{"en":"to go birdwatching","cn":"去观鸟","ex":{"en":"I've birded from coast to coast and north to south.","cn":"我从东海岸到西海岸、从北到南都观鸟过。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鸟；禽","en":"A bird is a creature with feathers and wings. Female birds lay eggs. Most birds can fly."},{"pos":"N-COUNT 可数名词","cn":"小妞儿（可能具冒犯意味）","en":"Some men refer to young women as birds. This use could cause offence."},{"pos":"PHRASE 短语","cn":"（尤指对孩子讲的）性知识","en":"Some people refer to the birds and the bees when they are talking about sex, especially to children."},{"pos":"PHRASE 短语","cn":"坐牢；蹲班房","en":"Someone who is doing bird is in prison.","ex":{"en":"They warned him that next time he'd find himself doing bird.","cn":"他们警告他下次他可能就要进监狱了。"}},{"pos":"PHRASE 短语","cn":"志趣相投的人；一路人","en":"If you refer to two people as birds of a feather, you mean that they have the same interests or are very similar."},{"pos":"PHRASE 短语","cn":"给…喝倒彩；嘘…","en":"If an audience gives someone the bird, they shout loudly in order to show their disappointment or disapproval."},{"pos":"PHRASE 短语","cn":"（表示侮辱）被竖中指/冲…竖中指","en":"If you get the bird or if someone gives you the bird, they make a rude gesture with their middle finger at you."},{"pos":"PHRASE 短语","cn":"到手之物","en":"A bird in the hand is something that you already have and do not want to risk losing by trying to get something else."},{"pos":"PHRASE 短语","cn":"消息灵通的人；某人","en":"If you say that a little bird told you about something, you mean that someone has told you about it, but you do not want to say who it was."},{"pos":"PHRASE 短语","cn":"（用于对人进行描述）…的人","en":"Some people use the phrase old bird to refer to someone and say what they are like.","ex":{"en":"As usual, Wheeler, a wise old bird, got it right","cn":"和往常一样，惠勒——一个非常聪明的人——又做对了。"}},{"pos":"PHRASE 短语","cn":"少见的人；稀有之物；凤毛麟角","en":"If you say that someone or something is a rare bird, you mean that they are very unusual."},{"pos":"PHRASE 短语","cn":"一石二鸟；一箭双雕；一举两得","en":"If you say that doing something will kill two birds with one stone, you mean that it will enable you to achieve two things that you want to achieve, rather than just one."}]},"examples":[{"en":"She is that rare bird: a politician with a social conscience.","cn":"她是这么一种少见的人：有社会良知的政治家。"},{"en":"The area has a wealth of bird life.","cn":"这个地区栖息着大量的鸟。"}]},"biased":{"media":{"uk":"media/uk/biased__gb_1.mp3","us":"media/us/biased__us_1.mp3"},"oxford":{"phon":"ˈbaɪəst","pos":"adjective","senses":[{"en":"tending to show favour towards or against one group of people or one opinion for personal reasons; making unfair judgements","cn":"有偏见的；倾向性的；片面的","ex":{"en":"biased information/sources/press reports","cn":"片面的信息／消息来源／新闻报道"}},{"en":"having a particular interest in one thing more than others","cn":"偏重；偏向","ex":{"en":"a school biased towards music and art","cn":"一所偏重音乐和艺术的学校"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有偏见的；有成见的；偏袒一方的","en":"If someone is biased, they prefer one group of people to another, and behave unfairly as a result. You can also say that a process or system is biased .","ex":{"en":"He seemed a bit biased against women in my opinion","cn":"我认为他好像对女性有点儿成见。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"偏向…的；偏重…的","en":"If something is biased towards one thing, it is more concerned with it than with other things.","ex":{"en":"In Japan firms are biased towards growth rather than profits","cn":"在日本，公司偏重于发展，而不是一味追求利润。"}}]},"examples":[{"en":"a school biased towards music and art","cn":"一所偏重音乐和艺术的学校"},{"en":"biased information/sources/press reports","cn":"片面的信息/消息来源/新闻报道"}]},"billionaire":{"media":{"uk":"media/uk/billionaire__gb_1.mp3","us":"media/us/billionaire__us_1.mp3"},"oxford":{"phon":"ˌbɪljəˈneə(r)","pos":"noun","senses":[{"en":"an extremely rich person, who has at least a thousand million pounds, dollars, etc. in money or property","cn":"巨富；亿万富翁","ex":{"en":"a Texas billionaire","cn":"德克萨斯州的亿万富翁"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"亿万富翁","en":"A billionaire is an extremely rich person who has money or property worth at least a thousand million pounds or dollars."}]}},"billion":{"media":{"uk":"media/uk/billion__gb_1.mp3","us":"media/us/billion__us_1.mp3"},"oxford":{"phon":"ˈbɪljən","pos":"number","senses":[{"en":"1 000 000 000; one thousand million","cn":"十亿","ex":{"en":"Worldwide sales reached 2.5 billion.","cn":"全球销售额达到了 25 亿。"}},{"en":"a very large amount","cn":"数以十亿计；大量","lab":"informal","ex":{"en":"Our immune systems are killing billions of germs right now.","cn":"我们的免疫系统正在杀死数以十亿计的细菌。"}},{"en":"1 000 000 000 000; one million million","cn":"一万亿","lab":"British English, old-fashioned，，"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"十亿","en":"A billion is a thousand million.","ex":{"en":"...3 billion dollars","cn":"30亿美元"}},{"pos":"QUANT-PLURAL 复数数量词","cn":"大量；无数","en":"If you talk about billions of people or things, you mean that there is a very large number of them but you do not know or do not want to say exactly how many.","ex":{"en":"Biological systems have been doing this for billions of years","cn":"生物系统亿万年来一直都是这样。"}}]},"examples":[{"en":"Two billion (people) worldwide are expected to watch the game.","cn":"预计全世界将有 20 亿人观看这场比赛。"},{"en":"Our immune systems are killing billions of germs right now.","cn":"我们的免疫系统正在杀死数以十亿计的细菌。"}]},"bicycle":{"oxford":{"phon":"ˈbaɪsɪkl","pos":"noun","senses":[{"en":"a road vehicle with two wheels that you ride by pushing the pedals with your feet","cn":"自行车；脚踏车","ex":{"en":"He got on his bicycle and rode off.","cn":"他骑上自行车走了。"}},{"en":"to go somewhere on a bicycle","cn":"骑自行车","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"自行车；脚踏车","en":"A bicycle is a vehicle with two wheels which you ride by sitting on it and pushing two pedals with your feet. You steer it by turning a bar that is connected to the front wheel."},{"pos":"VERB 动词","cn":"骑自行车","en":"If you bicycle somewhere, you cycle there.","ex":{"en":"I bicycled on towards the sea.","cn":"我继续骑着自行车朝海边走。"}}]},"media":{"img":["media/ldoce/img/bicycle.jpg","media/pic/cycles_comp.jpg"],"uk":"media/uk/bicycle__gb_1.mp3","us":"media/us/bicycle__us_1.mp3"},"examples":[{"en":"We went for a bicycle ride on Sunday.","cn":"我们星期天骑自行车兜风了。"},{"en":"He got on his bicycle and rode off.","cn":"他骑上自行车走了。"}]},"bicycling":{"oxford":{"phon":"ˈbaɪsɪkl","pos":"noun","senses":[{"en":"a road vehicle with two wheels that you ride by pushing the pedals with your feet","cn":"自行车；脚踏车"},{"en":"( old-fashioned ) to go somewhere on a bicycle","cn":"骑自行车"}]}},"biological":{"oxford":{"phon":"ˌbaɪəˈlɒdʒɪkl","pos":"adjective","senses":[{"en":"connected with the science of biology","cn":"生物学的","ex":{"en":"the biological sciences","cn":"生物科学"}},{"en":"connected with the processes that take place within living things","cn":"生物的；与生命过程有关的","ex":{"en":"the biological effects of radiation","cn":"辐射对生物体的影响"}},{"en":"related by blood","cn":"有血缘关系的；亲生的","ex":{"en":"a child’s biological parents (= natural parents, not the people who adopted him/her)","cn":"孩子的亲生父母"}},{"en":"using enzymes (= chemical substances that are found in plants and animals) to get clothes, etc. clean","cn":"加酶的","ex":{"en":"biological and non-biological powders","cn":"加酶和不加酶的洗衣粉"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"生物的；与生命过程有关的","en":"Biological is used to describe processes and states that occur in the bodies and cells of living things.","ex":{"en":"The living organisms somehow concentrated the minerals by biological processes","cn":"生命体通过某种生物过程聚集矿物质。"}},{"pos":"ADJ 形容词","cn":"生物学的","en":"Biological is used to describe activities concerned with the study of living things.","ex":{"en":"...all aspects of biological research associated with leprosy.","cn":"与麻风病相关的生物学研究的各个方面"}},{"pos":"ADJ 形容词","cn":"（武器、战争）生物性的，使用细菌的","en":"Biological weapons and biological warfare involve the use of bacteria or other living organisms in order to attack human beings, animals, or plants.","ex":{"en":"Such a war could result in the use of chemical and biological weapons.","cn":"这样的战争可能导致使用生化武器。"}},{"pos":"ADJ 形容词","cn":"（虫害防治）利用生物的","en":"Biological pest control is the use of bacteria or other living organisms in order to destroy other organisms which are harmful to plants or crops.","ex":{"en":"...Jim Litsinger, a consultant on biological control of agricultural pests.","cn":"农业虫害生物防治顾问吉姆·利钦格"}},{"pos":"ADJ 形容词","cn":"（父母）生身的，亲生的","en":"A child's biological parents are the man and woman who caused him or her to be born, rather than other adults who look after him or her.","ex":{"en":"...foster parents for young teenagers whose biological parents have rejected them.","cn":"被亲生父母抛弃的青少年的养父母"}},{"pos":"ADJ 形容词","cn":"（洗衣粉）含酶的，生物性的","en":"A biological washing powder contains substances called enzymes which dissolve dirt."}]},"media":{"uk":"media/uk/biological__gb_1.mp3","us":"media/us/biological__us_1.mp3"},"examples":[{"en":"the biological control of pests (= using living organisms to destroy them, not chemicals)","cn":"对害虫的生物防治（用生物天敌而非化学药剂来消灭它们）"},{"en":"a child's biological parents (= natural parents, not the people who adopted him/her)","cn":"孩子的亲生父母"}]},"bind":{"oxford":{"phon":"baɪnd","pos":"verb","senses":[{"en":"to tie somebody/something with rope, string, etc. so that they/it cannot move or are held together strongly","cn":"捆绑；系","g":"[transitive]","lab":"formal","sc":"tie with rope/cloth","ex":{"en":"She was bound to a chair.","cn":"她被捆在一把椅子上。"}},{"en":"to tie a long thin piece of cloth around something","cn":"（用长布条）缠绕","g":"[transitive]","lab":"formal","sc":"tie with rope/cloth","ex":{"en":"She bound up his wounds.","cn":"她把他的伤口包扎好。"}},{"en":"to make people, organizations, etc. feel united so that they live or work together more happily or effectively","cn":"（使）联合在一起，结合","g":"[transitive]","sc":"form united group","ex":{"en":"Organizations such as schools and clubs bind a community together.","cn":"诸如学校、俱乐部等机构使社区成为一个整体。"}},{"en":"to force somebody to do something by making them promise to do it or by making it their duty to do it","cn":"约束；迫使","g":"[transitive, usually passive]","sc":"make somebody do something","ex":{"en":"He had been bound to secrecy (= made to promise not to tell people about something).","cn":"他被迫保守秘密。"}},{"en":"to stick together or to make things stick together in a solid mass","cn":"（使）黏合，凝结","g":"[intransitive, transitive]","sc":"stick together","ex":{"en":"Add an egg yolk to make the mixture bind.","cn":"加个蛋黄使混合料凝结。"}},{"en":"to fasten the pages of a book together and put them inside a cover","cn":"装订","g":"[transitive, usually passive]","sc":"book","ex":{"en":"two volumes bound in leather","cn":"两卷皮面装帧的书"}},{"en":"to sew a piece of material to the edge of something to decorate it or to make it stronger","cn":"给…镶边；缝牢…的边","g":"[transitive, often passive]","sc":"sew edge","ex":{"en":"The blankets were bound with satin.","cn":"那些毯子是用缎子包边的。"}},{"en":"an annoying situation that is often difficult to avoid","cn":"窘境","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使紧密联系；使关系密切","en":"If something binds people together, it makes them feel as if they are all part of the same group or have something in common.","ex":{"en":"It is the memory and threat of persecution that binds them together.","cn":"遭受迫害的记忆和威胁把他们紧紧联系在一起。"}},{"pos":"VERB 动词","cn":"约束；限制；使负有义务（或责任）","en":"If you are bound by something such as a rule, agreement, or restriction, you are forced or required to act in a certain way.","ex":{"en":"The Luxembourg-based satellite service is not bound by the same strict rules as the BBC","cn":"设在卢森堡的卫星服务公司无须像英国广播公司那样遵守严格的规定。"}},{"pos":"VERB 动词","cn":"束；绑；捆绑","en":"If you bind something or someone, you tie rope, string, tape, or other material around them so that they are held firmly.","ex":{"en":"Bind the ends of the cord together with thread.","cn":"用线把这根绳子的两端捆扎起来。"}},{"pos":"VERB 动词","cn":"装订（书籍）","en":"When a book is bound, the pages are joined together and the cover is put on.","ex":{"en":"Each volume is bound in bright-coloured cloth","cn":"每一卷都采用色彩亮丽的布面装帧。"}},{"pos":"V-ERG 及物/不及物动词","cn":"结合","en":"If one chemical or particle is bound to another, it becomes attached to it or reacts with it to form a single particle or substance.","ex":{"en":"At present nobody understands why these three quarks which are in the proton are bound together","cn":"目前还没有人知道质子里面的这三个夸克为什么会结合在一起。"}},{"pos":"VERB 动词","cn":"（烹饪中）（使）黏合","en":"In cookery, if you bind a mixture of food, you form it into a mass by mixing it with a sticky substance.","ex":{"en":"Bind the mixture with the raw minced liver and cook for 3 minutes more.","cn":"让混合物滚上切碎的生肝脏，烹饪3分钟以上。"}},{"pos":"N-SING 单数名词","cn":"左右为难的境地；进退两难的境地","en":"If you are in a bind, you are in a difficult situation, usually because you have to make a decision or a choice and whatever decision or choice you make will have unpleasant consequences.","ex":{"en":"This puts the politicians in a bind as to what course to take","cn":"这使政治家们左右为难，不知道该如何处理。"}},{"pos":"N-SING 单数名词","cn":"令人不快的事物；无聊的事物","en":"If you say that something is a bind, you mean that it is unpleasant and boring to do.","ex":{"en":"It is expensive to buy and a bind to carry home.","cn":"买这个费用很贵，搬回家也费劲。"}},{"pos":"","cn":"","en":"相关词组：bind over"}]},"media":{"uk":"media/uk/bind__gb_1.mp3","us":"media/us/bind__us_1.mp3"},"examples":[{"en":"Organizations such as schools and clubs bind a community together.","cn":"诸如学校、俱乐部等机构使社区成为一个整体。"},{"en":"He was left bound and gagged (= tied up and with a piece of cloth tied over his mouth).","cn":"他被捆起来，用布封住嘴，扔在那儿了。"}]},"bitterness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a strong sharp taste that is not sweet, like black coffee without sugar – used especially about chocolate, medicine etc","cn":""},{"en":"having a taste that makes your tongue sting slightly","cn":""}]},"examples":[{"en":"I feel very bitter about it.","cn":"","src":"ld"},{"en":"If he failed, it would be a bitter disappointment to his parents.","cn":"","src":"ld"}],"media":{"uk":"media/uk/bitterness__gb_1.mp3","us":"media/us/bitterness__us_1.mp3"},"oxford":{"phon":"ˈbɪtənəs","pos":"noun","senses":[{"en":"angry and unhappy feelings caused by the belief that you have been treated unfairly","cn":"愤愤不平的","ex":{"en":"The pay cut caused bitterness among the staff.","cn":"减薪令员工十分愤懑。"}},{"en":"the fact of being very serious and unpleasant, with a lot of anger and hate involved","cn":"激烈而不愉快的；充满愤怒与仇恨的","ex":{"en":"the bitterness of the conflict/dispute","cn":"冲突/争端的激烈程度"}},{"en":"the fact of having a strong, unpleasant taste that is not sweet","cn":"味苦的","ex":{"en":"The flowers of the hop plant add bitterness to the beer.","cn":"忽布花给啤酒增添了苦味。"}}]}},"bi":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"同 bisexual","en":"Bi means the same as bisexual ."}]},"media":{"uk":"media/uk/bi__1_gb_1.mp3","us":"media/us/bi__1_us_1.mp3"},"oxford":{"phon":"baɪ","pos":"adjective","senses":[{"en":"sexually attracted to people of more than one gender","cn":"双性恋的"},{"en":"two; twice; double","cn":"二；两次；两倍；双","ex":{"en":"bilingual","cn":"双语的"},"pos":"combining form"}]}},"biscuit":{"media":{"uk":"media/uk/biscuit__gb_1.mp3","us":"media/us/biscuit__us_1.mp3"},"oxford":{"phon":"ˈbɪskɪt","pos":"noun","senses":[{"en":"a small flat dry cake for one person, usually sweet, and baked until hard","cn":"饼干","g":"[countable]","lab":"British English","ex":{"en":"a packet/tin of chocolate biscuits","cn":"一包／一盒巧克力饼干"}},{"en":"a soft bread roll, often eaten with gravy","cn":"松饼（食用时常佐以肉汁）","g":"[countable]","lab":"North American English"},{"en":"a pale yellow-brown colour","cn":"浅黄褐色","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"饼干","en":"A biscuit is a small flat cake that is crisp and usually sweet."},{"pos":"N-COUNT 可数名词","cn":"烤饼；小圆面包","en":"A biscuit is a small round dry cake that is made with baking powder, baking soda, or yeast."},{"pos":"PHRASE 短语","cn":"（强调吃惊）竟然做出这种（愚蠢、粗野或自私的）事情","en":"If someone has done something very stupid, rude, or selfish, you can say that they take the biscuit or that what they have done takes the biscuit, to emphasize your surprise at their behaviour."}]},"examples":[{"en":"You've done some stupid things before, but this really takes the biscuit!","cn":"你以前确也干过些蠢事，但这一次实在吓人！"},{"en":"a packet of chocolate biscuits","cn":"一包巧克力饼干"}]},"bill":{"media":{"uk":"media/uk/bill__gb_1.mp3","us":"media/us/bill__us_1.mp3"},"oxford":{"phon":"bɪl","pos":"noun","senses":[{"en":"a document that shows how much you owe somebody for goods or services","cn":"账单","lab":"informal","sc":"for payment","ex":{"en":"the phone/electricity/gas bill","cn":"话费／电费／煤气费账单"}},{"en":"a piece of paper that shows how much you have to pay for the food and drinks that you have had in a restaurant","cn":"（餐馆的）账单","lab":"especially British English","sc":"for payment","ex":{"en":"Let's ask for the bill.","cn":"我们结账吧。"}},{"en":"a piece of paper money","cn":"纸币；钞票","lab":"North American English","sc":"money","ex":{"en":"a ten-dollar bill","cn":"一张十美元的钞票"}},{"en":"a written suggestion for a new law that is presented to a country’s parliament so that its members can discuss it","cn":"（提交议会讨论的）议案，法案","sc":"in parliament","ex":{"en":"to introduce/approve/oppose a bill","cn":"提出/批准/反对一项法案"}},{"en":"a programme of entertainment at a theatre, etc.","cn":"（剧院等的）节目单","sc":"at theatre, etc.","ex":{"en":"a horror double bill (= two horror films shown one after the other)","cn":"恐怖片两场连映"}},{"en":"a notice in a public place to advertise an event","cn":"海报；招贴；广告","sc":"advertisement","ex":{"en":"Post no bills (= a notice warning people not to stick bills in a particular place).","cn":"禁止招贴"}},{"en":"the hard pointed or curved outer part of a bird’s mouth","cn":"鸟嘴；喙","sc":"of birds"},{"en":"having the type of bill mentioned","cn":"有…形喙的","sc":"of birds","ex":{"en":"long-billed waders","cn":"长嘴涉禽"}},{"en":"the stiff front part of a cap that sticks out above your eyes","cn":"帽舌；帽檐","lab":"both North American English","sc":"on hat"},{"en":"to send somebody a bill for something","cn":"开账单，发账单（要求付款）","sc":"ask for payment","ex":{"en":"Please bill me for the books.","cn":"请就所购的书给我开列账单。"},"pos":"verb"},{"en":"to advertise or describe somebody/something in a particular way","cn":"把（某人或事物）宣传为…","g":"[usually passive]","sc":"advertise","ex":{"en":"He was billed as the new Tom Cruise.","cn":"他被宣传为新汤姆·克鲁斯。"},"pos":"verb"},{"en":"to advertise that somebody/something will do something","cn":"宣布…将做某事","g":"[usually passive]","sc":"advertise","ex":{"en":"She was billed to speak on ‘China—Yesterday and Today’.","cn":"据宣传，她要发表题为“中国——昨天和今天”的演讲。"},"pos":"verb"},{"en":"a first name for boys, short for William","cn":"比尔（男子名，William 缩写）","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（商品或服务费用的）账单","en":"A bill is a written statement of money that you owe for goods or services. →see usage note at:","ex":{"en":"They couldn't afford to pay the bills","cn":"他们无力支付这些账单。"}},{"pos":"VERB 动词","cn":"给…开送账单","en":"If you bill someone for goods or services you have provided them with, you give or send them a bill stating how much money they owe you for these goods or services.","ex":{"en":"Are you going to bill me for this?","cn":"你们会给我开这个的账单吗？"}},{"pos":"N-SING 单数名词","cn":"（餐馆的）账单","en":"The bill in a restaurant is a piece of paper on which the price of the meal you have just eaten is written and which you are given before you pay."},{"pos":"N-COUNT 可数名词","cn":"纸币；钞票","en":"A bill is a piece of paper money.","ex":{"en":"...a large quantity of US dollar bills.","cn":"大量的美钞"}},{"pos":"N-COUNT 可数名词","cn":"议案；法案","en":"In government, a bill is a formal statement of a proposed new law that is discussed and then voted on.","ex":{"en":"This is the toughest crime bill that Congress has passed in a decade","cn":"这是十年来国会通过的最严厉的一项刑事法案。"}},{"pos":"N-SING 单数名词","cn":"演出人员名单","en":"The bill of a show or concert is a list of the entertainers who will take part in it."},{"pos":"VERB 动词","cn":"宣传（某人）将参加演出","en":"If someone is billed to appear in a particular show, it has been advertised that they are going to be in it.","ex":{"en":"She was billed to play the Red Queen in Snow White.","cn":"海报宣传她会扮演《白雪公主》中的“红王后”。"}},{"pos":"VERB 动词","cn":"宣传（某人或某物有某种特质或能力）","en":"If you bill a person or event as a particular thing, you advertise them in a way that makes people think they have particular qualities or abilities.","ex":{"en":"They bill it as Britain's most exciting museum.","cn":"他们宣称它是英国最有趣的博物馆。"}},{"pos":"N-COUNT 可数名词","cn":"鸟嘴；喙","en":"A bird's bill is its beak."},{"pos":"PHRASE 短语","cn":"适合需要；符合要求","en":"If you say that someone or something fits the bill or fills the bill, you mean that they are suitable for a particular job or purpose.","ex":{"en":"If you fit the bill, send a CV to Rebecca Rees.","cn":"如果你符合要求，就寄一份简历给丽贝卡·里斯。"}},{"pos":"PHRASE 短语","cn":"付账；买单","en":"If you have to foot the bill for something, you have to pay for it.","ex":{"en":"Who is footing the bill for her extravagant holiday?","cn":"谁会为她奢侈的假日买单？"}},{"pos":"PHRASE 短语","cn":"身体状况良好","en":"If a doctor gives you a clean bill of health, they tell you that you are fit and healthy.","ex":{"en":"President Mitterrand, 75, has been given a clean bill of health by doctors in Paris.","cn":"巴黎的医生们告诉75岁的密特朗总统，他的身体非常健康。"}}]},"examples":[{"en":"She was billed to speak on ‘China — Yesterday and Today’.","cn":"海报上说她要发表题为“中国 — 昨天和今天”的演讲。"},{"en":"The builders sent an invoice for £250.","cn":"营造商发出了一张 250 英镑的发票。"}]},"bills":{"oxford":{"phon":"bɪl","pos":"noun","senses":[{"en":"a piece of paper that shows how much you owe sb for goods or services","cn":"账单"},{"en":"a piece of paper that shows how much you have to pay for the food and drinks that you have had in a restaurant （","cn":"餐馆的）账单"}]},"media":{"uk":"media/uk/bill__gb_1.mp3","us":"media/us/bill__us_1.mp3"}},"biology":{"oxford":{"phon":"baɪˈɒlədʒi","pos":"noun","senses":[{"en":"the scientific study of the life and structure of plants and animals","cn":"生物学","ex":{"en":"a degree in biology","cn":"生物学学位"}},{"en":"the way in which the body and cells of a living thing behave","cn":"生理","ex":{"en":"How far is human nature determined by biology?","cn":"人性在多大程度上是由其生理因素决定的？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"生物学","en":"Biology is the science which is concerned with the study of living things."},{"pos":"N-UNCOUNT 不可数名词","cn":"（生物的）生命机理","en":"The biology of a living thing is the way in which its body or cells behave.","ex":{"en":"The biology of these diseases is terribly complicated.","cn":"这些疾病的机理极其复杂。"}}]},"media":{"uk":"media/uk/biology__gb_1.mp3","us":"media/us/biology__us_1.mp3"},"examples":[{"en":"How far is human nature determined by biology?","cn":"人性在多大程度上是由其生理因素决定的？"},{"en":"the biology of marine animals","cn":"海洋动物的生理习性"}]},"bitter":{"media":{"uk":"media/uk/bitter__gb_1.mp3","us":"media/us/bitter__us_1.mp3"},"oxford":{"phon":"ˈbɪtə(r)","pos":"adjective","senses":[{"en":"having a strong, unpleasant taste; not sweet","cn":"味苦的","lab":"figurative","ex":{"en":"Black coffee leaves a bitter taste in the mouth.","cn":"不加牛奶的咖啡在嘴里留下苦味。"}},{"en":"very serious and unpleasant, with a lot of anger and hate involved","cn":"激烈而不愉快的；充满愤怒与仇恨的","ex":{"en":"a long and bitter dispute","cn":"漫长而激烈的争论"}},{"en":"feeling angry and unhappy because you feel that you have been treated unfairly","cn":"愤愤不平的","ex":{"en":"She is very bitter about losing her job.","cn":"她丢掉了工作，心里很不服气。"}},{"en":"making you feel very unhappy; caused by great unhappiness","cn":"令人不快的；使人悲痛的；由痛苦引起的","g":"[usually before noun]","ex":{"en":"to weep/shed bitter tears","cn":"伤心落泪"}},{"en":"extremely cold and unpleasant","cn":"严寒的","ex":{"en":"bitter cold","cn":"严寒"}},{"en":"a type of beer with a dark colour and a strong bitter taste, that is very popular in England and Wales","cn":"苦啤酒（在英格兰和威尔士很受欢迎）","g":"[uncountable, countable]","lab":"British English","ex":{"en":"A pint of bitter, please.","cn":"请来一品脱苦啤酒。"},"pos":"noun"},{"en":"a strong bitter alcoholic liquid that is made from plants and added to other alcoholic drinks","cn":"苦酒原汁（从植物中提取的苦酒精液体，可添加到其他酒精饮料中）","g":"[uncountable + singular or plural verb]","ex":{"en":"gin with a dash of bitters","cn":"掺了少量苦酒汁的杜松子酒"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"激烈的；猛烈的；充满敌意的","en":"In a bitter argument or conflict, people argue very angrily or fight very fiercely.","ex":{"en":"...the scene of bitter fighting during the Second World War.","cn":"第二次世界大战期间激烈的战斗场面"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"怨恨的；愤愤不平的","en":"If someone is bitter after a disappointing experience or after being treated unfairly, they continue to feel angry about it.","ex":{"en":"She is said to be very bitter about the way she was sacked","cn":"据说，她对自己被以如此方式解雇而感到愤愤不平。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（经历或感觉）令人非常失望的，痛苦的，辛酸的","en":"A bitter experience makes you feel very disappointed. You can also use bitter to emphasize feelings of disappointment.","ex":{"en":"I think the decision was a bitter blow from which he never quite recovered","cn":"我想这个决定对他是个沉重的打击，从此以后他一蹶不振。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"寒冷的；刺骨的","en":"Bitter weather, or a bitter wind, is extremely cold.","ex":{"en":"Outside, a bitter east wind was accompanied by flurries of snow.","cn":"外面，刺骨的东风伴着阵阵小雪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（味道）苦的","en":"A bitter taste is sharp, not sweet, and often slightly unpleasant.","ex":{"en":"The leaves taste rather bitter.","cn":"这些叶子味道相当苦。"}},{"pos":"N-MASS 物质名词","cn":"苦啤酒","en":"Bitter is a kind of beer that is light brown in colour.","ex":{"en":"...a pint of bitter.","cn":"一品脱苦啤酒"}},{"pos":"PHRASE 短语","cn":"坚持到底；拼到底","en":"If you say that you will continue doing something to the bitter end, especially something difficult or unpleasant, you are emphasizing that you will continue doing it until it is completely finished.","ex":{"en":"The guerrillas would fight to the bitter end, he said, in order to achieve their main goal.","cn":"他说，游击队员会为实现主要目标而战斗到底。"}},{"pos":"","cn":"","en":"a bitter pill→see: ;"}]},"examples":[{"en":"I've learnt from bitter experience not to trust what he says.","cn":"我已从痛苦的经验中得到了教训，不再相信他的话。"},{"en":"Losing the match was a bitter disappointment for the team.","cn":"输掉这场比赛对这个队来说是一件伤心失望的事。"}]},"binary":{"media":{"uk":"media/uk/binary__gb_1.mp3","us":"media/us/binary__us_1.mp3"},"oxford":{"phon":"ˈbaɪnəri","pos":"adjective","senses":[{"en":"using only 0 and 1 as a system of numbers","cn":"二进制的（用 0 和 1 记数）","lab":"computing, mathematics，，","ex":{"en":"the binary system","cn":"二进制"}},{"en":"based on only two numbers; consisting of two parts","cn":"仅基于两个数字的；二元的；由两部分组成的","lab":"specialist","ex":{"en":"binary code/numbers","cn":"二进制代码／数字"}},{"en":"a system of numbers that uses only 0 and 1","cn":"（计算机运算系统）二进制","g":"[uncountable]","lab":"computing, mathematics，，","ex":{"en":"The computer performs calculations in binary and converts the results to decimal.","cn":"计算机以二进制数运算，然后把运算结果转换为十进制数。"},"pos":"noun"},{"en":"a way of looking at something that divides it into just two different categories","cn":"（计算机运算系统）二进制","g":"[countable]","ex":{"en":"They argue that it is important to go beyond the binaries of male and female, gay and straight.","cn":"他们认为，重要的是要超越男性和女性、同性恋和异性恋的二元对立。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"二进制的，二进位的(尤用于计算机领域)","en":"The binary system expresses numbers using only the two digits 0 and 1. It is used especially in computing."},{"pos":"N-UNCOUNT 不可数名词","cn":"二进制","en":"Binary is the binary system of expressing numbers.","ex":{"en":"The machine does the calculations in binary.","cn":"这台机器采用二进制进行计算。"}},{"pos":"ADJ 形容词","cn":"二元的；有两个不同部分的","en":"Binary describes something that has two different parts.","ex":{"en":"...a binary star.","cn":"双星"}}]},"examples":[{"en":"The computer performs calculations in binary and converts the results to decimal.","cn":"计算机以二进制数运算，然后把运算结果转换为十进制数。"},{"en":"binary code/numbers","cn":"二进制代码/数字"}]},"bit":{"media":{"uk":"media/uk/bit__gb_1.mp3","us":"media/us/bit__us_1.mp3"},"oxford":{"phon":"bɪt","pos":"noun","senses":[{"en":"rather; to some extent","cn":"有点；在某种程度上","g":"[singular]","lab":"especially British English","sc":"small amount","ex":{"en":"These trousers are a bit tight.","cn":"这条裤子有点紧。"}},{"en":"a short time or distance","cn":"稍顷；短距离","g":"[singular]","lab":"especially British English","sc":"small amount","ex":{"en":"Wait a bit!","cn":"等会儿！"}},{"en":"a small amount or piece of something","cn":"小量；小块","g":"[countable]","lab":"especially British English","sc":"small amount","ex":{"en":"Here are some useful bits of information.","cn":"这儿有一些有用的零星信息。"}},{"en":"a part of something larger","cn":"（事物的）一部分，一段","g":"[countable]","lab":"especially British English","sc":"part of something","ex":{"en":"The best bit of the holiday was seeing the Grand Canyon.","cn":"假期中最精彩的片段是参观大峡谷。"}},{"en":"a large amount","cn":"许多；大量","g":"[singular]","lab":"especially British English, informal，，","sc":"large amount","ex":{"en":"‘How much does he earn?’ ‘Quite a bit!’","cn":"“他有多少收入？”“挺多的！”"}},{"en":"the smallest unit of information used by a computer","cn":"比特，二进制位，位（计算机的最小信息单位）","g":"[countable]","sc":"computing"},{"en":"a metal bar that is put in a horse’s mouth so that the rider can control it","cn":"嚼子","g":"[countable]","sc":"for horse"},{"en":"a tool or part of a tool for drilling (= making) holes","cn":"钻头；刀头；钎头","g":"[countable]","sc":"tool"},{"en":"an amount of money equal to 12½ cents","cn":"12.5 分；一角二分半","g":"[countable]","lab":"North American English, informal，，","sc":"money"},{"en":"a person’s sexual organs","cn":"（人的）生殖器","g":"[plural]","lab":"British English, informal，，","sc":"sexual organs"}]},"collins":{"senses":[{"pos":"QUANT 数量词","cn":"一点；少许；少量","en":"A bit of something is a small amount of it.","ex":{"en":"All it required was a bit of work","cn":"这事儿只需稍费工夫就可以了。"}},{"pos":"PHRASE 短语","cn":"稍微；稍稍；有点儿","en":"A bit means to a small extent or degree. It is sometimes used to make a statement less extreme.","ex":{"en":"This girl was a bit strange","cn":"这个女孩有点儿古怪。"}},{"pos":"PHRASE 短语","cn":"有点儿；有几分；稍微","en":"You can use a bit of to make a statement less forceful. For example, the statement 'It's a bit of a nuisance' is less forceful than 'It's a nuisance'.","ex":{"en":"It's all a bit of a mess","cn":"有点儿乱七八糟。"}},{"pos":"PHRASE 短语","cn":"很多；相当多；相当大","en":"Quite a bit means quite a lot.","ex":{"en":"They're worth quite a bit of money","cn":"它们值不少钱。"}},{"pos":"PHRASE 短语","cn":"稍微（多或少一些）","en":"You use a bit before 'more' or 'less' to mean a small amount more or a small amount less.","ex":{"en":"I still think I have a bit more to offer","cn":"我还是认为我能再稍微多付出一点儿。"}},{"pos":"PHRASE 短语","cn":"一会儿，片刻（英国英语中亦用for a bit）","en":"If you do something a bit, you do it for a short time. In British English, you can also say that you do something for a bit .","ex":{"en":"Let's wait a bit","cn":"我们等一会儿吧。"}},{"pos":"N-COUNT 可数名词","cn":"小部分；小块；片段","en":"A bit of something is a small part or section of it.","ex":{"en":"That's the bit of the meeting that I missed","cn":"那就是会议上我错过的那一小段。"}},{"pos":"N-COUNT 可数名词","cn":"一点；小块；小片；小段","en":"A bit of something is a small piece of it.","ex":{"en":"Only a bit of string looped round a nail in the doorpost held it shut.","cn":"仅仅是靠缠在门柱钉子上的一小段细绳把门关紧。"}},{"pos":"N-COUNT 可数名词","cn":"（一组事物中的）一个，一项，一件","en":"You can use bit to refer to a particular item or to one of a group or set of things. For example, a bit of information is an item of information.","ex":{"en":"There was one bit of vital evidence which helped win the case","cn":"一个关键的证据帮助打赢了这场官司。"}},{"pos":"N-SING 单数名词","cn":"（表示不重要）所有相关的零七碎八","en":"You use bit in expressions such as the charity bit and the whole marriage bit to refer to everything that is involved in something, when you do not think it is important."},{"pos":"N-COUNT 可数名词","cn":"位，比特（计算机的最小信息量单位）","en":"In computing, a bit is the smallest unit of information that is held in a computer's memory. It is either 1 or 0. Several bits form a byte."},{"pos":"N-COUNT 可数名词","cn":"12.5美分","en":"A bit is 12 1/2 cents; mainly used in expressions such as two bits, which means 25 cents, or four bits, which means 50 cents."},{"pos":"N-COUNT 可数名词","cn":"马嚼子；马衔","en":"A bit is a piece of metal that is held in a horse's mouth and is used to control the horse when you are riding."},{"pos":"","cn":"","en":"Bit is the past tense of bite."},{"pos":"PHRASE 短语","cn":"一点点地；逐渐地","en":"If something happens bit by bit, it happens in stages.","ex":{"en":"Bit by bit I began to understand what they were trying to do.","cn":"我逐渐明白了他们想要干什么。"}},{"pos":"PHRASE 短语","cn":"急欲摆脱束缚做事；急于开始","en":"If someone is champing at the bit or is chomping at the bit, they are very impatient to do something, but they are prevented from doing it, usually by circumstances that they have no control over.","ex":{"en":"I expect you're champing at the bit, so we'll get things going as soon as we can.","cn":"我希望你努力打开局面，这样我们就能尽快把事情做起来。"}},{"pos":"PHRASE短语","cn":"尽微薄之力；尽一份力","en":"If you do your bit, you do something that, to a small or limited extent, helps to achieve something."},{"pos":"PHRASE 短语","cn":"完全和…一样…；…程度丝毫不逊色于…","en":"You say that one thing is every bit as good, interesting, or important as another to emphasize that the first thing is just as good, interesting, or important as the second.","ex":{"en":"My dinner jacket is every bit as good as his.","cn":"我的晚礼服和他的一样好。"}},{"pos":"PHRASE 短语","cn":"有点儿过分；不合情理","en":"If you say that something is a bit much, you are annoyed because you think someone has behaved in an unreasonable way.","ex":{"en":"It's a bit much expecting me to dump your boyfriend for you.","cn":"指望我替你甩掉你的男朋友，有点儿过分了吧？"}},{"pos":"PHRASE 短语","cn":"一点儿也不；毫不","en":"You use not a bit when you want to make a strong negative statement.","ex":{"en":"I'm really not a bit surprised","cn":"我真的一点儿也不觉得惊讶。"}},{"pos":"PHRASE 短语","cn":"并非如此；根本没有；一点儿没有","en":"You say not a bit of it to emphasize that something that you might expect to be the case is not the case.","ex":{"en":"Did he give up? Not a bit of it!","cn":"他放弃了吗？根本没有！"}},{"pos":"PHRASE 短语","cn":"各种零碎东西；七零八碎的东西","en":"You can use bits and pieces or bits and bobs to refer to a collection of different things."},{"pos":"PHRASE 短语","cn":"（对工作等）满腔热忱，义无反顾","en":"If you get the bit between your teeth, or take the bit between your teeth, you become very enthusiastic about a job you have to do."},{"pos":"PHRASE 短语","cn":"成为碎片","en":"If something is smashed or blown to bits, it is broken into a number of pieces. If something falls to bits, it comes apart so that it is in a number of pieces.","ex":{"en":"She found a pretty yellow jug smashed to bits.","cn":"她发现一个漂亮的黄色小罐被摔得粉碎。"}},{"pos":"","cn":"","en":"thrilled to bits→see: ;"}]},"examples":[{"en":"The school play was a huge success — the audience roared with laughter at all the funny bits.","cn":"学校的演出获得了巨大成功，所有的滑稽片段都令观众哄堂大笑。"},{"en":"I can lend you fifty pounds, if you want. That should help a bit.","cn":"如果你需要，我可以借给你五十英镑。那应该有些帮助。"}]},"bishop":{"oxford":{"phon":"ˈbɪʃəp","pos":"noun","senses":[{"en":"a senior priest in charge of the work of the Church in a city or district","cn":"主教","ex":{"en":"the Bishop of Oxford","cn":"牛津区主教"}},{"en":"a piece used in the game of chess that is like a bishop’s hat in shape and can move any number of squares in a diagonal line","cn":"（国际象棋中的）象"}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"主教","en":"A bishop is a clergyman of high rank in the Roman Catholic, Anglican, and Orthodox churches."},{"pos":"N-COUNT 可数名词","cn":"（国际象棋中的）象","en":"In chess a bishop is a piece that can be moved diagonally across the board on squares that are the same colour."}]},"media":{"uk":"media/uk/bishop__gb_1.mp3","us":"media/us/bishop__us_1.mp3"},"examples":[{"en":"the Bishop of Oxford","cn":"牛津区主教"},{"en":"Bishop Harries","cn":"哈里斯主教"}]},"bib":{"media":{"uk":"media/uk/bib__gb_1.mp3","us":"media/us/bib__us_1.mp3","img":["media/ldoce/img/bib.jpg"]},"oxford":{"phon":"bɪb","pos":"noun","senses":[{"en":"a piece of cloth or plastic that you fasten around a baby’s neck to protect its clothes while it is eating","cn":"围嘴；围兜"},{"en":"a piece of cloth or plastic with a number or special colours on it that people wear on their chests and backs when they are taking part in a sport, so that people know who they are","cn":"（运动员佩戴的）号码布，彩色身份标记","lab":"especially British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"围嘴儿","en":"A bib is a piece of cloth or plastic which is worn by very young children to protect their clothes while they are eating."}]}},"bilingualism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"能说两种语言的能力；双语能力","en":"Bilingualism is the ability to speak two languages equally well."}]}},"birds":{"oxford":{"phon":"bɜːd","pos":"noun","senses":[{"en":"a creature that is covered with feathers and has two wings and two legs. Most birds can fly.","cn":"鸟；禽"},{"en":"( BrE ) ( slang, sometimes offensive ) a way of referring to a young woman","cn":"姑娘；妞"}]},"media":{"img":["media/pic/birds_comp.jpg"]}},"biggest":{"oxford":{"phon":"bɪɡ","pos":"adjective","senses":[{"en":"large in size, degree, amount, etc. （","cn":"体积、程度、数量等）大的，巨大的"},{"en":"( informal ) older","cn":"年龄较大的"}]}},"bilinguals":{"oxford":{"phon":"ˌbaɪˈlɪŋɡwəl","pos":"adj.","senses":[{"en":"able to speak two languages equally well","cn":"会说两种语言的"},{"en":"using two languages; written in two languages","cn":"用两种语言（写）的"}]}},"bits":{"oxford":{"phon":"bɪt","pos":"noun","senses":[{"en":"( used as an adverb","cn":"用作副词 ) ( especially BrE ) rather 有点儿；稍微"},{"en":"( especially BrE ) a short time or distance","cn":"稍顷；短距离"}]}},"bicyclists":{"oxford":{"phon":"ˈbaɪsɪklɪst","pos":"noun","senses":[{"en":"( old-fashioned in British English, formal in North American English","cn":"英式英语中属过时用语，美式英语中属正式用语 ) a person who rides a bicycle 骑自行车者"}]}},"bins":{"oxford":{"phon":"bɪn","pos":"noun","senses":[{"en":"a container that you put waste in","cn":"垃圾箱"},{"en":"a large container, usually with a lid, for storing things in （","cn":"有盖）大容器，箱，柜"}]}},"billions":{"oxford":{"phon":"ˈbɪljən","pos":"number","senses":[{"en":"1 000 000 000; one thousand million","cn":"十亿"},{"en":"You say a, one, two, several, etc. billion without a final ‘s’ on ‘billion’. Billions (of … ) can be used if there is no number or quantity before it. Always use a plural verb with billion or billions , except when an amount of mo","cn":"说 a, one, two, several, etc. billion 时， billion 后面不加 s。若前面没有数目或数量，可用 billions (of...)。除非指金额，billion 和 billions 均用复数动词"}]}},"bigger":{"oxford":{"phon":"bɪɡ","pos":"adjective","senses":[{"en":"large in size, degree, amount, etc. （","cn":"体积、程度、数量等）大的，巨大的"},{"en":"( informal ) older","cn":"年龄较大的"}]}},"billowed":{"oxford":{"phon":"ˈbɪləʊ","pos":"verb","senses":[{"en":"to fill with air and swell out","cn":"鼓起"},{"en":"if smoke, cloud, etc. billows , it rises and moves in a large mass （","cn":"烟雾等）涌出，大量冒出"}]}},"bible":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"《圣经》","en":"The Bible is the holy book on which the Jewish and Christian religions are based."},{"pos":"N-COUNT 可数名词","cn":"一本《圣经》","en":"A Bible is a copy of the Bible."},{"pos":"N-COUNT 可数名词","cn":"宝典；权威著作","en":"If someone describes a book or magazine about their job or interest as their bible, they mean that it is the best and most useful book about the subject.","ex":{"en":"...the photographer's bible — Amateur Photographer.","cn":"摄影师的宝典——《业余摄影师》"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the holy book of the Christian religion, consisting of the Old Testament and the New Testament 〔","cn":"基督教〕《圣经》"},{"en":"a copy of the bible 〔","cn":"一册〕《圣经》"},{"en":"the most useful and important book on a particular subject 〔","cn":"某一主题的〕权威著作，宝典"}]},"collocations":{"phrases":["ADJ. Holy","VERB + BIBLE read, study","BIBLE + VERB say sth, tell sb sth, teach sth The Bible teaches that all people are equal before God.","BIBLE + NOUN reading, story | study","PREP. in the ~ You can read the story of Noah in the Bible."]},"media":{"uk":"media/ldoce/hwd/bre/e/ld5_bible.mp3","us":"media/ldoce/hwd/ame/e/ld5_bible.mp3"},"examples":[{"en":"the stamp-collector's bible","cn":"集邮者的宝典"},{"en":"It's the anatomy student's bible!","cn":"这是解剖学专业学生的“《圣经》”！"}],"oxford":{"phon":"ˈbaɪbl","pos":"noun","senses":[{"en":"the holy book of the Christian religion, consisting of the Old Testament and the New Testament","cn":"基督教的《圣经》（包括《旧约》和《新约》）","g":"[singular]"},{"en":"the holy book of the Jewish religion, consisting of the Torah (or Law), the prophets and the Writings","cn":"犹太教的《圣经》（包括《律法书》《先知书》及《圣录》）","g":"[singular]"},{"en":"a copy of the holy book of the Christian or Jewish religion","cn":"一册（基督教或犹太教的）《圣经》","g":"[countable]"},{"en":"a book containing important information on a subject, that you refer to very often","cn":"权威著作（或参考书）","g":"[countable]","ex":{"en":"the stamp-collector’s bible","cn":"集邮者的宝典"}}]}},"bizarre":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奇异的；古怪的","en":"Something that is bizarre is very odd and strange.","ex":{"en":"The game was also notable for the bizarre behaviour of the team's manager","cn":"这场比赛也因球队主教练怪异的举动而尽人皆知。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very strange or very different from what you are used to","cn":""},{"en":"extremely strange and different from what is usually considered normal","cn":""},{"en":"extremely strange and unconnected with real life or normal experiences, like something out of a dream","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A person, object, or situation that's bizarre is very odd or unusual in appearance, style, or character. If your teacher walked into class wearing a purple boa, cat's eyes glasses and three inch heels, you might comment, \"How bizarre !\""}]},"collocations":{"phrases":["VERBS be, seem, sound | become | find sth I found the whole situation very bizarre.","ADV. most, truly, very He walked off in a most bizarre fashion. | quite, totally He made some totally bizarre comments. | increasingly | a l"]},"media":{"uk":"media/ldoce/hwd/bre/9/bizarre0205.mp3","us":"media/ldoce/hwd/ame/d/bizarre.mp3"},"examples":[{"en":"a bizarre situation/incident/story","cn":"稀奇古怪的局势/事件/故事"},{"en":"bizarrely dressed","cn":"穿着奇装异服"}],"oxford":{"phon":"bɪˈzɑː(r)","pos":"adjective","senses":[{"en":"very strange or unusual","cn":"极其怪诞的；异乎寻常的","ex":{"en":"a bizarre situation/incident/story","cn":"稀奇古怪的局势／事件／故事"}}]}},"binding":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有约束力的；必须遵守的；应履行的","en":"A binding promise, agreement, or decision must be obeyed or carried out.","ex":{"en":"...proposals for a legally binding commitment on nations to stabilise emissions of carbon dioxide","cn":"要求各国作出具有法律约束力的承诺以稳定二氧化碳排放量的提案"}},{"pos":"N-VAR 可变名词","cn":"（书籍的）封面","en":"The binding of a book is its cover.","ex":{"en":"Its books are noted for the quality of their paper and bindings.","cn":"其图书以纸质优良、封面精美而闻名。"}},{"pos":"N-VAR 可变名词","cn":"镶边；边饰；绲边","en":"Binding is a strip of material that you put round the edge of a piece of cloth or other object in order to protect or decorate it.","ex":{"en":"...the Regency mahogany dining table with satinwood binding.","cn":"摄政时期用缎木镶边的红木餐桌"}},{"pos":"N-VAR 可变名词","cn":"捆绑物；包扎物","en":"Binding is a piece of rope, cloth, tape, or other material that you wrap around something so that it can be gripped firmly or held in place."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a promise, agreement etc that must be obeyed","cn":"具有约束力[必须履行]的合同/承诺/协议等"},{"en":"a book cover 〔","cn":"书籍的〕封面"},{"en":"material sewn or stuck along the edge of a piece of cloth for strength or decoration 〔","cn":"布料的〕镶边，滚边"}]},"collocations":{"phrases":["VERBS be | become","ADV. absolutely | legally, morally","PREP. on/upon The decisions of the European Court are binding on the United Kingdom."]},"media":{"uk":"media/ldoce/hwd/bre/6/binding_adj0205.mp3","us":"media/ldoce/hwd/ame/5/binding1.mp3"},"examples":[{"en":"a binding promise/agreement/contract","cn":"有约束力的承诺/协议/合同"}],"oxford":{"phon":"ˈbaɪndɪŋ","pos":"adjective","senses":[{"en":"that must be obeyed because it is accepted in law","cn":"必须遵守的；有法律约束力的","ex":{"en":"a binding promise/agreement/contract","cn":"有约束力的承诺／协议／合同"}},{"en":"the cover that holds the pages of a book together","cn":"（书的）封皮","g":"[countable, uncountable]","ex":{"en":"rare books in leather bindings","cn":"皮革装订的珍本书籍"},"pos":"noun"},{"en":"cloth that is fastened to the edge of something to protect or decorate it","cn":"镶边；绲边","g":"[countable, uncountable]","pos":"noun"},{"en":"a device on a ski that holds the heel and toe of your boot in place and releases the boot if you fall","cn":"（滑雪板的）滑雪鞋固定装置","g":"[countable]","pos":"noun"}]}},"biography":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（人物）传记","en":"A biography of someone is an account of their life, written by someone else."},{"pos":"N-UNCOUNT 不可数名词","cn":"传记（文学体裁）","en":"Biography is the branch of literature which deals with accounts of people's lives.","ex":{"en":"...a volume of biography and criticism.","cn":"一册传记和评论文章"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a book about imaginary people and events","cn":""},{"en":"books that describe imaginary people and events","cn":""},{"en":"novels and plays that are considered to be important works of art","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A biography is an account of somebody's life written by somebody else, complete with details of the most important parts."}]},"collocations":{"phrases":["ADJ. authorized, official | unauthorized, unofficial | brief, potted The book gives potted biographies of all the major painters.","VERB + BIOGRAPHY work on, write | publish | read","PREP. ~ by a biography by Antonia Fraser | ~ of a biography of the prime minister"]},"media":{"uk":"media/ldoce/hwd/bre/e/biography0205.mp3","us":"media/ldoce/hwd/ame/d/biography.mp3"},"examples":[{"en":"Boswell's biography of Johnson","cn":"博斯韦尔写的约翰逊传"},{"en":"Boswell’s biography of Samuel Johnson","cn":"鲍斯韦尔为塞缪尔·约翰逊写的传记"}],"oxford":{"phon":"baɪˈɒɡrəfi","pos":"noun","senses":[{"en":"the story of a person’s life written by somebody else; this type of writing","cn":"传记；传记作品","ex":{"en":"Boswell’s biography of Johnson","cn":"博斯韦尔写的约翰逊传"}}]}},"binge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"放纵；无节制","en":"If you go on a binge, you do too much of something, such as drinking alcohol, eating, or spending money.","ex":{"en":"She went on occasional drinking binges.","cn":"她偶尔会狂饮一通。"}},{"pos":"VERB 动词","cn":"放纵；不加节制","en":"If you binge, you do too much of something, such as drinking alcohol, eating, or spending money.","ex":{"en":"I haven't binged since 1986","cn":"1986年以来我就没有纵情狂欢过。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short period when you do too much of something, such as eating or drinking 〔","cn":"短时间内的〕放纵﹔大吃大喝"},{"en":"to do too much of something, such as eating or drinking, in a short period of time","cn":"放纵﹔大吃大喝"}]},"vocab":{"pos":"v n","senses":[{"en":"A binge is a brief period of doing something excessively. You might celebrate your birthday by indulging in a banana cream pie binge if that's your very favorite dessert."}]},"collocations":{"phrases":["ADJ. drinking, drunken | eating","VERB + BINGE go on, have He went on a drunken binge when he heard the bad news."]},"media":{"uk":"media/ldoce/hwd/bre/f/binge_n0205.mp3","us":"media/ldoce/hwd/ame/e/binge.mp3"},"examples":[{"en":"When she's depressed she binges on chocolate.","cn":"她心情不好的时候就大嚼巧克力。"},{"en":"One of the symptoms is binge eating.","cn":"症状之一是饮食无度。"}],"oxford":{"phon":"bɪndʒ","pos":"noun","senses":[{"en":"a short period of time when somebody does too much of a particular activity, especially eating or drinking alcohol","cn":"（短时间的）狂热活动，寻欢作乐，大吃大喝","ex":{"en":"to go on a binge","cn":"饮酒作乐"}},{"en":"to eat or drink too much, especially without being able to control yourself","cn":"大吃大喝；狂欢作乐","ex":{"en":"When she's depressed she binges on chocolate.","cn":"她心情不好的时候就大嚼巧克力。"},"pos":"verb"}]}},"birthmark":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胎记；胎痣","en":"A birthmark is a mark on someone's skin that has been there since they were born."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mark on your skin that spoils its appearance","cn":""},{"en":"a small dark, sometimes raised, mark on your skin","cn":""},{"en":"small light brown marks on your skin, especially on your face but also on your arms, shoulders etc","cn":""}]},"collocations":{"phrases":["ADJ. large, small | disfiguring, unsightly | faint | purple, red","VERB + BIRTHMARK have","BIRTHMARK + VERB fade"]},"media":{"uk":"media/ldoce/hwd/bre/2/birthmark0205.mp3","us":"media/ldoce/hwd/ame/b/birthmark.mp3"},"examples":[{"en":"Paul had a birthmark on his left cheek.","cn":"保罗左脸颊上有块胎记。"}],"oxford":{"phon":"ˈbɜːθmɑːk","pos":"noun","senses":[{"en":"a red or brown mark on a person’s skin that has been there since they were born","cn":"胎记；胎痣"}]}},"bikini":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"比基尼泳装","en":"A bikini is a two-piece swimming costume worn by women."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of clothes worn by women for swimming, which consists of a top part covering the breasts, and a bottom part","cn":"比基尼[三点式]泳装"}]},"vocab":{"pos":"n","senses":[{"en":"A bikini is a two-piece women's bathing suit. Bikinis are usually skimpy, and a particularly small one inspired a song from 1960 called \"Itsy Bitsy Teeny Weeny Yellow Polka Dot Bikini .”"}]},"collocations":{"phrases":["ADJ. brief, minuscule, skimpy","BIKINI + NOUN bottoms, top | line •"]},"media":{"img":["media/ldoce/img/bikini.jpg"],"uk":"media/ldoce/hwd/bre/4/bikini0205.mp3","us":"media/ldoce/hwd/ame/6/bikini.mp3"},"oxford":{"phon":"bɪˈkiːni","pos":"noun","senses":[{"en":"a piece of clothing in two pieces worn for swimming and lying in the sun","cn":"比基尼泳装，三点式泳装"}]}},"binoculars":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"双筒望远镜","en":"Binoculars consist of two small telescopes joined together side by side, which you look through in order to look at things that are a long way away."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pair of special glasses, that you hold up to your eyes to look at objects that are a long distance away","cn":"双筒望远镜"}]},"vocab":{"pos":"n","senses":[{"en":"Birdwatchers often use binoculars to get a better look at their feathered friends. When you look through binoculars , far-off things appear much closer."}]},"collocations":{"phrases":["ADJ. high-powered, powerful","QUANT. pair","VERB + BINOCULARS look through | focus, train He focused his binoculars on the building in the distance. | adjust | lift, raise She raised h","PREP. through ~ watching the race through binoculars"]},"media":{"img":["media/ldoce/img/binoculars.jpg","media/thumb/binoculars.jpg"],"uk":"media/ldoce/hwd/bre/a/brelasdebinoculars.mp3","us":"media/ldoce/hwd/ame/6/binoculars.mp3"},"examples":[{"en":"We looked at the birds through binoculars.","cn":"我们用双筒望远镜观鸟。"},{"en":"a pair of binoculars","cn":"一副双筒望远镜"}],"oxford":{"phon":"bɪˈnɒkjələz","pos":"noun","senses":[{"en":"an instrument, like two small telescopes fixed together, that makes objects that are far away seem nearer when you look through it","cn":"双筒望远镜","ex":{"en":"a pair of binoculars","cn":"一副双筒望远镜"}}]}},"bias":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"偏见；偏心；偏袒","en":"Bias is a tendency to prefer one person or thing to another, and to favour that person or thing.","ex":{"en":"Bias against women permeates every level of the judicial system","cn":"各级司法机构普遍存在对女性的偏见。"}},{"pos":"N-VAR 可变名词","cn":"偏好；偏爱","en":"Bias is a concern with or interest in one thing more than others.","ex":{"en":"The Department has a strong bias towards neuroscience.","cn":"这个系特别偏重神经科学。"}},{"pos":"VERB 动词","cn":"使有偏见；使偏向","en":"To bias someone means to influence them in favour of a particular choice.","ex":{"en":"We mustn't allow it to bias our teaching.","cn":"我们决不允许它影响我们的教学。"}},{"pos":"PHRASE 短语","cn":"斜裁","en":"A dress or skirt that is cut on the bias or that is bias-cut has been cut diagonally across the material so that it hangs down in a particular way.","ex":{"en":"The fabric, cut on the bias, hangs as light as a cobweb off a woman's body.","cn":"这块斜裁料如蛛网一般轻盈地从一女子身上垂下来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an opinion about whether a person, group, or idea is good or bad that influences how you deal with it","cn":"偏见﹐成见﹔偏心"},{"en":"a natural skill or interest in one type of thing 〔","cn":"某一方面的〕天赋﹔偏爱"},{"en":"in a diagonal direction","cn":"偏斜地﹔成对角地"}]},"vocab":{"pos":"1 n v 2 n adj","senses":[{"en":"Use the noun bias to mean a preference for one thing over another, especially an unfair one."}]},"collocations":{"phrases":["ADJ. clear, definite, marked, obvious, strong | left-wing, right-wing | cultural, political","VERB + BIAS have The newspaper has a clear bias towards the Conservative Party. | display, show | avoid, eliminate, reduce | correct We have","BIAS + VERB creep in, exist Bias often creeps in through the wording of questions.","PREP. with/without ~ All material must be selected and presented without bias. | with a ~ a newspaper with a strong left-wing bias | ~ again"]},"media":{"uk":"media/ldoce/hwd/bre/1/bias_n0205.mp3","us":"media/ldoce/hwd/ame/b/bias1.mp3"},"examples":[{"en":"The experiment contained an error which could bias the results.","cn":"这项实验有一个错误，可能导致结果出现偏差。"},{"en":"Employers must consider all candidates impartially and without bias.","cn":"雇主必须公平而毫无成见地考虑所有求职者。"}],"oxford":{"phon":"ˈbaɪəs","pos":"noun","senses":[{"en":"a strong feeling in favour of or against one group of people, or one side in an argument, often not based on fair judgement","cn":"偏见；偏心；偏向","g":"[uncountable, countable, usually singular]","lab":"British English","ex":{"en":"accusations of political bias in news programmes (= that reports are unfair and show favour to one political party)","cn":"对新闻报道中政治倾向性的指责"}},{"en":"an interest in one thing more than others; a special ability","cn":"偏爱；特殊能力","g":"[countable, usually singular]","ex":{"en":"The course has a strong practical bias.","cn":"这个课程偏重实用。"}},{"en":"the fact that the results of research or an experiment are not accurate because a particular factor has not been considered when collecting the information","cn":"（研究或实验结果的）偏倚，偏差","g":"[uncountable, countable]","ex":{"en":"If a response rate is low, the risk of bias in the findings will be greater.","cn":"如果回应率低，调查结果出现偏差的风险会增加。"}},{"en":"the bias of a piece of cloth is an edge cut diagonally across the threads","cn":"斜裁","g":"[uncountable, singular]","ex":{"en":"The skirt is cut on the bias.","cn":"这条裙子是斜裁的。"}},{"en":"to unfairly influence somebody’s opinions or decisions","cn":"使有偏见；使偏心；使偏向","ex":{"en":"The newspapers have biased people against her.","cn":"报章使人们对她产生了偏见。"},"pos":"verb"},{"en":"to have an effect on the results of research or an experiment so that they do not show the real situation","cn":"影响（研究或实验结果）以致产生偏差","ex":{"en":"The experiment contained an error which could bias the results.","cn":"这项实验有一个错误，可能导致结果出现偏差。"},"pos":"verb"}]}},"bike":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"自行车；摩托车","en":"A bike is a bicycle or a motorcycle."},{"pos":"VERB 动词","cn":"骑自行车（或摩托车）去（某处）","en":"To bike somewhere means to go there on a bicycle.","ex":{"en":"I biked home from the beach.","cn":"我从海边骑自行车回家。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to go somewhere in a car","cn":""},{"en":"to go somewhere in a car, on a bicycle etc - use this especially when you are comparing different methods of travelling","cn":""},{"en":"to go somewhere on a bicycle","cn":""}]},"collocations":{"phrases":["ADJ. mountain, racing, touring, trail | exercise","VERB + BIKE ride | get on He got on his bike and rode off. | get off | come off, fall off She came off her bike when it skidded on some wet ","BIKE + VERB get/have a puncture","BIKE + NOUN ride | shed","PREP. by ~ Did you come by bike? | on a/the ~ watching the boys on their bikes","PHRASES lean/prop a bike against sth"]},"media":{"uk":"media/ldoce/hwd/bre/3/bike_n0205.mp3","us":"media/ldoce/hwd/ame/1/bike.mp3"},"examples":[{"en":"I'll bike the contract over to you this afternoon.","cn":"今天下午我骑摩托车把合同给你送过去。"},{"en":"The activities on offer include sailing and mountain biking.","cn":"提供的活动项目有帆船运动和山地骑车。"}],"oxford":{"phon":"baɪk","pos":"noun","senses":[{"en":"a bicycle","cn":"自行车；脚踏车","ex":{"en":"I used to ride my bike around the neighbourhood for hours.","cn":"我过去常骑着车在周边街区闲逛，一逛就是几个小时。"}},{"en":"a motorcycle","cn":"摩托车"},{"en":"to go somewhere on a bicycle or motorcycle","cn":"骑自行车（或摩托车）；骑车","g":"[intransitive]","lab":"informal","ex":{"en":"My dad bikes to work every day.","cn":"我爸爸每天骑车上班。"},"pos":"verb"},{"en":"to send something to somebody by motorcycle","cn":"骑摩托车递送","g":"[transitive]","lab":"informal","ex":{"en":"I'll bike the contract over to you this afternoon.","cn":"今天下午我骑摩托车把合同给你送过去。"},"pos":"verb"}]}},"bibliography":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（有关某一专题的）书目","en":"A bibliography is a list of books on a particular subject.","ex":{"en":"At the end of this chapter there is a select bibliography of useful books.","cn":"本章末尾列有一份有用的精选书目。"}},{"pos":"N-COUNT 可数名词","cn":"（参考或引证的）文献目录，参考书目","en":"A bibliography is a list of the books and articles that are referred to in a particular book."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an alphabetically arranged list of all the names and subjects in a book","cn":""},{"en":"a list, usually printed at the front of a book, which shows the main parts that the book is divided into","cn":""},{"en":"a list of all the books and articles on a particular subject, or all the books and articles that are used when you write something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A bibliography is a list of writings by an author, such as the lengthy bibliography of Joyce Carol Oates, or a list of writings someone uses in a project, like the bibliography at the end of a research paper."}]},"collocations":{"phrases":["ADJ. brief, select, selective | comprehensive, extensive an extensive bibliography of books and articles","VERB + BIBLIOGRAPHY compile, put together | contain, include | publish | consult Consult the bibliography for further reading on the subject","PREP. in a/the ~ You'll find the professor's book in the bibliography. | ~ of The book includes a selective bibliography of works on French "]},"media":{"uk":"media/ldoce/hwd/bre/2/bibliography0205.mp3","us":"media/ldoce/hwd/ame/d/bibliography.mp3"},"oxford":{"phon":"ˌbɪbliˈɒɡrəfi","pos":"noun","senses":[{"en":"a list of books or articles about a particular subject or by a particular author; the list of books, etc. that have been used by somebody writing an article, etc.","cn":"（某一专题或作家的）书目，索引；参考书目","g":"[countable]","ex":{"en":"There is a useful bibliography at the end of each chapter.","cn":"在每一章后附有一份有用的参考书目。"}},{"en":"the study of the history of books and their production","cn":"目录学；文献学；书志学","g":"[uncountable]"}]}}});
